package com.connectjob.controller;
import com.connectjob.model.Job; import com.connectjob.repository.JobRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/jobs") public class JobController { private final JobRepository repo; public JobController(JobRepository r){repo=r;} @GetMapping public List<Job> all(@RequestParam(required=false) String q){return q==null||q.isBlank()?repo.findAll():repo.findByTitleContainingIgnoreCaseOrCompanyContainingIgnoreCase(q,q);} @GetMapping("/{id}") public Job one(@PathVariable Long id){return repo.findById(id).orElseThrow();} @PostMapping public Job create(@RequestBody Job j){j.setId(null);return repo.save(j);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }
